exports.accepted_type:
QuantyraNullCone.membership_count_eq_binomial.{u_1} {Omega : Type u_1} [MeasurableSpace Omega]
  (mu : MeasureTheory.Measure Omega) [MeasureTheory.IsProbabilityMeasure mu] (n : ℕ) {S : Set Omega}
  (hS : MeasurableSet S) : QuantyraNullCone.membershipCountLaw mu n S = QuantyraNullCone.binomialCountLaw n (mu.real S)

QuantyraNullCone.finite_upper_tail_pvalue.{u_1} {Alpha : Type u_1} [Fintype Alpha] [LinearOrder Alpha]
  [MeasurableSpace Alpha] (mu : MeasureTheory.Measure Alpha) [MeasureTheory.IsFiniteMeasure mu] {alpha : ℝ}
  (ha : 0 ≤ alpha) : mu.real {x | mu.real (Set.Ici x) ≤ alpha} ≤ alpha

QuantyraNullCone.finite_lower_tail_pvalue.{u_1} {Alpha : Type u_1} [Fintype Alpha] [LinearOrder Alpha]
  [MeasurableSpace Alpha] (mu : MeasureTheory.Measure Alpha) [MeasureTheory.IsFiniteMeasure mu] {alpha : ℝ}
  (ha : 0 ≤ alpha) : mu.real {x | mu.real (Set.Iic x) ≤ alpha} ≤ alpha

QuantyraNullCone.calibration_detector_on_diamond {epsilon : ℝ} (he : 0 ≤ epsilon) {p : QuantyraNullCone.DiamondPoint}
  (hp : p ∈ QuantyraNullCone.diamond) :
  QuantyraNullCone.calibrationDetector epsilon p = (1 - epsilon) / QuantyraNullCone.calibrationDensity epsilon p
